namespace Workspace;
require dirname(__DIR__).'/app/bootstrap.php';require ROOT.'/app/Web.php';
$n=0;function fbCheck(bool $v,string $why):void{global $n;if(!$v)throw new \RuntimeException($why);++$n;}function fbKey():string{return bin2hex(random_bytes(16));}function fbDeny(callable $f):void{try{$f();}catch(Problem){fbCheck(true,'denied');return;}throw new \RuntimeException('Expected denial');}function fbCleanup(string $d):void{foreach(new \FilesystemIterator($d) as $f){if($f->isDir()&&!$f->isLink())fbCleanup($f->getPathname());else unlink($f->getPathname());}rmdir($d);}
// PostgreSQL modes require an empty disposable target; never point them at production.
$native=in_array('--native-postgres',$argv,true);$transfer=in_array('--postgres',$argv,true);
if($native&&$transfer)throw new \RuntimeException('Choose one PostgreSQL mode');
$dir=sys_get_temp_dir().'/cw-books-'.fbKey();mkdir($dir,0700);putenv('WORKSPACE_DATA='.$dir);putenv('WORKSPACE_DB='.($native?'pgsql':'sqlite'));
try{
$db=null;if($native){$db=postgresConnect();postgresEmpty($db);migratePostgres($db,true);}else $db=database(true);addUser($db,'owner@example.test','Owner','owner','sample-password-only',true);addUser($db,'acc@example.test','Accountant','accountant','sample-password-only');$owner=organizationUser($db,['id'=>1,'name'=>'Owner']);$acc=organizationUser($db,['id'=>2,'name'=>'Accountant']);$_SESSION=['mfa_at'=>time(),'csrf'=>'test'];
$a=createProject($db,$owner,fbKey(),['title'=>'A','kind'=>'client']);$b=createProject($db,$owner,fbKey(),['title'=>'B','kind'=>'client']);foreach([$a,$b] as $p)changeMembership($db,$owner,'project',$p,2,true);
$ea=invoiceEntitySave($db,$owner,['name'=>'Entity A','registration'=>'A','address'=>'Street']);$eb=invoiceEntitySave($db,$owner,['name'=>'Entity B','registration'=>'B','address'=>'Street']);$supplier=clientCommand($db,$owner,fbKey(),'client.party',['name'=>'Supplier']);$today=gmdate('Y-m-d');$past=gmdate('Y-m-d',time()-86400);$start=gmdate('Y-m-d',time()-86400*10);$future=gmdate('Y-m-d',time()+86400*10);
$ac=fn($u,$act,$f=[])=>accountingCommand($db,$u,fbKey(),'accounting.'.$act,$f);$cmd=fn($u,$act,$f,$k=null)=>bookCommand($db,$u,$k??fbKey(),'books.'.$act,$f);
$ac($owner,'init');$p0=$ac($owner,'period',['starts_on'=>$start,'ends_on'=>$future]);$opening=$ac($owner,'prepare',['period_id'=>$p0,'pairs'=>"EUR 1000 3000 100.00\nUSD 1000 3000 100.00\nGBP 1000 3000 20.00",'evidence'=>'Bank proof','EUR'=>'100','USD'=>'100','PLN'=>'0','GBP'=>'20','RUB'=>'0']);$ac($acc,'approve',['id'=>$opening,'version'=>1,'note'=>'Verified']);
$cmd($owner,'assign',['entity_id'=>$ea,'project_id'=>$a]);$cmd($owner,'assign',['entity_id'=>$eb,'project_id'=>$b]);$entry=(int)query($db,"SELECT id FROM accounting_entries WHERE kind='opening' AND currency='EUR'")->fetchColumn();$cmd($owner,'allocate',['entity_id'=>$ea,'entry_id'=>$entry]);fbDeny(fn()=>$cmd($owner,'allocate',['entity_id'=>$eb,'entry_id'=>$entry]));fbDeny(fn()=>$cmd($owner,'assign',['entity_id'=>$eb,'project_id'=>$a]));
$usdOpening=(int)query($db,"SELECT id FROM accounting_entries WHERE kind='opening' AND currency='USD'")->fetchColumn();$cmd($owner,'allocate',['entity_id'=>$eb,'entry_id'=>$usdOpening]);
$unallocated=bookTrial($db,1,0,$start,$past);fbCheck(array_keys($unallocated)===['GBP']&&$unallocated['GBP']['1000']['closing']===2000,'unallocated opening is not lost');
$pa=$cmd($owner,'period',['entity_id'=>$ea,'starts_on'=>$start,'ends_on'=>$past]);$pb=$cmd($owner,'period',['entity_id'=>$eb,'starts_on'=>$start,'ends_on'=>$past]);foreach([$ea,$eb] as $e)$cmd($owner,'period',['entity_id'=>$e,'starts_on'=>$today,'ends_on'=>$future]);
$bill=['entity_id'=>$ea,'project_id'=>$a,'supplier_id'=>$supplier,'reference'=>'A-1','booked_on'=>$past,'due_on'=>$past,'currency'=>'EUR','amount'=>'80','memo'=>'Supplier invoice'];$k=fbKey();$id=$cmd($acc,'bill',$bill,$k);fbCheck($cmd($acc,'bill',$bill,$k)===$id,'accrual idempotent');fbDeny(fn()=>$cmd($acc,'bill',$bill));fbDeny(fn()=>$cmd($acc,'bill',['project_id'=>$b,'reference'=>'Wrong']+$bill));
$idb=$cmd($acc,'bill',['entity_id'=>$eb,'project_id'=>$b,'reference'=>'B-1']+$bill);$request=$cmd($acc,'pay',['entity_id'=>$ea,'id'=>$id,'amount'=>'30','booked_on'=>$past,'reference'=>'P-1']);$requestB=$cmd($acc,'pay',['entity_id'=>$eb,'id'=>$idb,'amount'=>'10','booked_on'=>$past,'reference'=>'P-B']);
$idUsd=$cmd($acc,'bill',['entity_id'=>$eb,'project_id'=>$b,'reference'=>'B-USD','currency'=>'USD','amount'=>'25']+$bill);$requestUsd=$cmd($acc,'pay',['entity_id'=>$eb,'id'=>$idUsd,'amount'=>'10','booked_on'=>$past,'reference'=>'P-USD']);
$read=fn($id)=>entity($db,'SELECT * FROM supplier_bills WHERE id=?',[$id]);fbCheck(bookBalance($db,$read($id))['outstanding']===8000,'pending is not paid');fbDeny(fn()=>$cmd($acc,'pay',['entity_id'=>$ea,'id'=>$id,'amount'=>'51','booked_on'=>$past,'reference'=>'Over']));fbDeny(fn()=>decidePayment($db,$acc,fbKey(),$request,'approve'));fbDeny(fn()=>$cmd($owner,'close',['entity_id'=>$ea,'id'=>$pa]));
decidePayment($db,$owner,fbKey(),$request,'approve');fbCheck(bookBalance($db,$read($id))['outstanding']===5000,'partial payment');fbCheck(accountingReconcile($db,1)['ok'],'cash reconciliation');$cash=(int)entity($db,'SELECT cash_entry_id FROM payment_requests WHERE id=?',[$request])['cash_entry_id'];fbDeny(fn()=>submitPayment($db,$owner,fbKey(),$a,[],$cash));fbDeny(fn()=>$ac($owner,'reverse',['id'=>$read($id)['entry_id'],'booked_on'=>$past,'memo'=>'bypass']));
$historical=bookTrial($db,1,$ea,$start,$past);$historicalDebt=bookPayableAt($db,$ea,$past);
fbCheck(array_keys($historical)===['EUR'],'A excludes B USD and unallocated GBP');
fbCheck($historical['EUR']['1000']===['opening'=>10000,'debit'=>0,'credit'=>3000,'closing'=>7000],'A opening and partial cash payment');
fbCheck($historical['EUR']['AP-LIAB']===['opening'=>0,'debit'=>3000,'credit'=>8000,'closing'=>-5000],'A liability postings');
fbCheck($historical['EUR']['AP-EXP']['closing']===8000,'A accrual');
fbCheck(bookPayableControl($historical,$historicalDebt)===['EUR'=>['ledger'=>5000,'debt'=>5000,'ok'=>true]],'A liability agrees with subledger before close');
$cmd($owner,'close',['entity_id'=>$ea,'id'=>$pa]);fbCheck(entity($db,'SELECT closed_at FROM finance_book_periods WHERE id=?',[$pb])['closed_at']===null,'independent periods');fbDeny(fn()=>submitPayment($db,$owner,fbKey(),$a,['income',100,'EUR',$past,'closed']));decidePayment($db,$owner,fbKey(),$requestB,'approve');decidePayment($db,$owner,fbKey(),$requestUsd,'approve');
$trialB=bookTrial($db,1,$eb,$start,$past);$controlB=bookPayableControl($trialB,bookPayableAt($db,$eb,$past));
fbCheck(count($controlB)===2&&$controlB['EUR']===['ledger'=>7000,'debt'=>7000,'ok'=>true]&&$controlB['USD']===['ledger'=>1500,'debt'=>1500,'ok'=>true],'B has independent EUR and USD liabilities');
fbCheck($trialB['USD']['1000']['closing']===9000,'B allocated USD cash');
$cmd($owner,'close',['entity_id'=>$eb,'id'=>$pb]);fbCheck(entity($db,'SELECT closed_at FROM finance_book_periods WHERE id=?',[$pa])['closed_at']!==null&&entity($db,'SELECT closed_at FROM finance_book_periods WHERE id=?',[$pb])['closed_at']!==null,'both periods closed');
$refund=$cmd($acc,'refund',['entity_id'=>$ea,'id'=>$id,'amount'=>'10','booked_on'=>$today,'reference'=>'R-1','original_request_id'=>$request]);decidePayment($db,$owner,fbKey(),$refund,'approve');fbCheck(bookBalance($db,$read($id))['outstanding']===6000,'refund restores debt');fbDeny(fn()=>$cmd($acc,'refund',['entity_id'=>$ea,'id'=>$id,'amount'=>'21','booked_on'=>$today,'reference'=>'R-2','original_request_id'=>$request]));
$page=booksPage($db,$owner,$ea,null,null);fbCheck($page['payableControl']['EUR']['ok']&&$page['cashControl']['EUR']['ok'],'control totals');fbCheck($page['totals']['EUR']['outstanding']===6000,'current debt');fbCheck($page['payableControl']['EUR']===['ledger'=>6000,'debt'=>6000,'ok'=>true],'refund restores ledger liability too');
fbCheck($page['trial']['EUR']['AP-LIAB']===['opening'=>-5000,'debit'=>0,'credit'=>1000,'closing'=>-6000],'next period opening and refund');
fbCheck(bookTrial($db,1,$ea,$start,$past)===$historical&&bookPayableAt($db,$ea,$past)===$historicalDebt,'historical ledger and debt immutable');
fbCheck(bookTrial($db,1,$eb,$start,$past)===$trialB,'other entity historical ledger immutable');
fbCheck($page['unallocated']['GBP']['1000']['closing']===2000,'unallocated GBP visible in page');
$cancel=$cmd($acc,'bill',['reference'=>'A-2','booked_on'=>$today,'due_on'=>$future]+$bill);$cmd($acc,'cancel',['entity_id'=>$ea,'id'=>$cancel,'booked_on'=>$today,'memo'=>'Duplicate document corrected']);fbCheck(bookBalance($db,$read($cancel))['outstanding']===0,'cancel unpaid');
$org=createOrganization($db,$owner,'Other');$foreign=organizationUser($db,['id'=>1,'name'=>'Owner'],$org);fbDeny(fn()=>booksPage($db,$foreign,$ea,null,null));$_SESSION['mfa_at']=0;fbDeny(fn()=>booksPage($db,$owner,$ea,null,null));$_SESSION['mfa_at']=time();ob_start();pageView('books','Финансовые книги',$owner,booksPage($db,$owner,$ea,null,null));$html=ob_get_clean();fbCheck(str_contains($html,'AP-LIAB')&&str_contains($html,'Supplier'),'web render');
if($transfer){$r=migrateToPostgres($dir.'/source.sqlite');$pg=postgresConnect();$page=booksPage($pg,$owner,$ea,null,null);fbCheck($page['payableControl']['EUR']['ok']&&$page['totals']['EUR']['outstanding']===6000&&accountingReconcile($pg,1)['ok'],'PG transfer and reconciliation');fbCheck(bookTrial($pg,1,$ea,$start,$past)===$historical&&bookTrial($pg,1,$eb,$start,$past)===$trialB,'PG transferred historical ledgers match SQLite');fbCheck($page['unallocated']['GBP']['1000']['closing']===2000&&$page['payableControl']['EUR']===['ledger'=>6000,'debt'=>6000,'ok'=>true],'PG transferred unallocated cash and refund');$pg=null;}
echo "OK · $n financial books DB checks (".($native?'native PostgreSQL':($transfer?'SQLite + PostgreSQL transfer':'SQLite')).")\n";
}finally{$db=null;fbCleanup($dir);}
